import React from 'react';
import classes from './AboutUs.module.scss';
import AboutUsData from './AboutUsData';
import { useNavigate } from 'react-router-dom';

const Section = ({ title, text }) => (
  <section className={classes.section}>
    {title && <h2>{title}</h2>}
    <p>{text}</p>
  </section>
);

const AboutUs = () => {
  const navigate = useNavigate();
  return (
    <div className={classes.pageContainer}>
      <h1>Соната — Где музыка обретает форму</h1>
      <img className={classes.logo} onClick={() => navigate('/')} src="/img/Logo.svg" alt="Logo.svg" />

      <main className={classes.mainContent}>
        <p className={classes.mainText} dangerouslySetInnerHTML={{ __html: AboutUsData.mainText }} />
        {AboutUsData.sections.map((section, index) => (
          <Section key={index} title={section.title} text={section.text} />
        ))}
      </main>
    </div>
  );
}

export default AboutUs;
